<?php require 'includes/auth.php';require 'config/database.php';require 'includes/csrf.php';if($_SERVER['REQUEST_METHOD']==='POST'){check();$pdo->prepare('INSERT INTO visits(prisoner_id,visitor_name,relationship,phone,visit_date,entry_time,status) VALUES(?,?,?,?,?,?,?)')->execute([$_POST['prisoner_id'],trim($_POST['visitor_name']),trim($_POST['relationship']),trim($_POST['phone']),$_POST['visit_date'],$_POST['entry_time'],trim($_POST['status'])]);header('Location: visitors.php');exit;}$rows=$pdo->query('SELECT * FROM visits ORDER BY id DESC')->fetchAll();$title='Visits';require 'includes/header.php';?><div class="row g-4"><div class="col-lg-4"><div class="box"><h4>Add Visits</h4><form method="post"><input type="hidden" name="token" value="<?=token()?>"><label class="form-label mt-2">Prisoner ID</label><input class="form-control" type="number" name="prisoner_id" required><label class="form-label mt-2">Visitor Name</label><input class="form-control" type="text" name="visitor_name" required><label class="form-label mt-2">Relationship</label><input class="form-control" type="text" name="relationship" required><label class="form-label mt-2">Phone</label><input class="form-control" type="text" name="phone" required><label class="form-label mt-2">Visit Date</label><input class="form-control" type="date" name="visit_date" required><label class="form-label mt-2">Entry Time</label><input class="form-control" type="time" name="entry_time" required><label class="form-label mt-2">Status</label><input class="form-control" type="text" name="status" required><button class="btn btn-primary mt-3">Save</button></form></div></div><div class="col-lg-8"><div class="box"><h2>Visits</h2><div class="table-responsive"><table class="table"><tr><th>Prisoner ID</th><th>Visitor Name</th><th>Relationship</th><th>Phone</th><th>Visit Date</th><th>Entry Time</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['prisoner_id'])?></td><td><?=htmlspecialchars($r['visitor_name'])?></td><td><?=htmlspecialchars($r['relationship'])?></td><td><?=htmlspecialchars($r['phone'])?></td><td><?=htmlspecialchars($r['visit_date'])?></td><td><?=htmlspecialchars($r['entry_time'])?></td><td><?=htmlspecialchars($r['status'])?></td></tr><?php endforeach;?></table></div></div></div></div><?php require 'includes/footer.php';?>